import * as esbuild from "esbuild";
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

const root = process.cwd();
const entry = resolve(root, "components/lyrics/spicy-webview-entry.ts");
const outFile = resolve(root, "components/lyrics/spicy-webview-bundle.ts");

const result = await esbuild.build({
  entryPoints: [entry],
  bundle: true,
  write: false,
  outdir: "spicy-webview-bundle",
  minify: true,
  format: "iife",
  target: ["chrome90", "safari15"],
  legalComments: "none",
  loader: {
    ".css": "css",
  },
});

const js = result.outputFiles.find((file) => file.path.endsWith(".js"))?.text || "";
const css = result.outputFiles.find((file) => file.path.endsWith(".css"))?.text || "";

if (!js) {
  throw new Error("Spicy Lyrics WebView bundle did not produce JavaScript output.");
}

function asStringLiteral(value) {
  return JSON.stringify(value)
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

const contents = `// Generated by scripts/build-spicy-webview-bundle.mjs. Do not edit by hand.\n// Renderer adapted from Spikerko/spicy-lyrics v6.3.15 (AGPL-3.0), commit 2a14863f8c29782f9ab3becff2b1360dfb74a4fb.\nexport const SPICY_WEBVIEW_JS = ${asStringLiteral(js)};\n\nexport const SPICY_WEBVIEW_CSS = ${asStringLiteral(css)};\n`;

await mkdir(dirname(outFile), { recursive: true });
await writeFile(outFile, contents, "utf8");
console.log(`Wrote ${outFile}`);

